#!/usr/bin/env python3
"""Apply the third external review's corrections to the praxis builder (v5.3 -> v5.4)."""
import json, re
from pathlib import Path

W = Path("/home/claude/work")
src = (W / "build_praxis_v53.js").read_text()

def rep(old, new, count=1):
    global src
    assert src.count(old) >= 1, f"anchor not found: {old[:90]}"
    src = src.replace(old, new, count)
def rx(pattern, new, flags=re.S):
    global src
    new_src, n = re.subn(pattern, lambda m: new, src, count=1, flags=flags)
    assert n == 1, f"regex not found: {pattern[:80]}"
    src = new_src

# ------------------------------------------------------------ 1. normalization: results provisional until rerun
rep('''The patched notebook (v3.2) derives the scale from training edges; the intensity cells are scheduled for regeneration under it, and the results reported here carry this qualification."),''',
    '''The patched notebook (v3.2) derives the scale from training edges. Because a small input change does not by itself establish that training trajectories, checkpoint selection, and hypothesis outcomes are unchanged, the R-GCN intensity results in Sections 4.7.2–4.8 are reported as provisional: the affected full, ablation, and event-only R-GCN models must be rerun under the corrected scale with unchanged seeds and training settings, the H2′–H4 comparisons recomputed, the tables and figures refreshed, and representative explanation checks repeated on any replacement checkpoints before the results are frozen (runner in Appendix A). The random-forest and Transformer runs are unaffected, since their inputs and configurations contain no overlap-weight normalization; the regime-target R-GCN runs are unaffected because the training-partition and global maxima coincide."),''')
rep('''  caption("Table", "Table 4.13. Trained models on the intensity target, ten seeds (mean ± SD), with tabular reference values from the five-seed grid."),''',
    '''  caption("Table", "Table 4.13. Trained models on the intensity target, ten seeds (mean ± SD), with tabular reference values from the five-seed grid. R-GCN values are provisional pending the training-only overlap-normalization rerun (Section 3.8.1); Transformer and tabular values are final."),''')
rep('''  caption("Table", "Table 4.14. Seed-level inference on paired differences (ten seeds; t-intervals; counts of seeds whose bin-cluster interval lies above zero; one-sided tests against the pre-registered margins)."),''',
    '''  caption("Table", "Table 4.14. Seed-level inference on paired differences (ten seeds; t-intervals; counts of seeds whose bin-cluster interval lies above zero; one-sided tests against the pre-specified margins). Rows involving the R-GCN are provisional pending the normalization rerun (Section 3.8.1)."),''')

# ------------------------------------------------------------ 2. XAI sample sizes and interpretation
old48 = src[src.index('  body("The fidelity, stability, relation-consistency, provenance, and latency package was executed'):src.index('  h2("4.9 Latency"),')]
new48 = '''  body("The fidelity, stability, relation-consistency, provenance, and latency package was executed against the final trained checkpoints for three representative runs: the regime target (trained R-GCN and Transformer, seed 42) and the intensity target at κ = 0 and κ = 1 (seed 0, trained R-GCN and Transformer of those cells). Each run reproduced the saved test predictions from the checkpoint and its serialized preprocessing state (maximum absolute probability error 1.9 × 10⁻¹⁰, 4.5 × 10⁻⁷, and 6.0 × 10⁻⁸ for the Transformer; ≤ 8.1 × 10⁻¹⁰ for the R-GCN), passed 8 of 8 provenance checks, and regenerated five analyst cases. The evaluations use different samples, stated here and in the table: feature-removal fidelity is evaluated on the full held-out set for the R-GCN (1,828 events on the regime target; 1,015 attack-block events in each intensity setting) and on a 128-event held-out sample for the Transformer; stability is evaluated on a 96-event sample for both models. Fidelity compares zeroing the ten top-ranked features with the mean over five draws of ten randomly chosen features, on two criteria: the AUPRC drop and the mean absolute change in predicted probability. Stability is the top-10 Jaccard overlap and Spearman rank correlation of the attribution under Gaussian input noise (σ = 0.01, three repeats). Table 4.16 summarizes; all of it is checkpoint-specific diagnostic evidence, not a population estimate of explanation quality."),
  caption("Table", "Table 4.16. Explanation validation on the final checkpoints. Fidelity rows: R-GCN 1,828 (regime) or 1,015 (intensity) events; Transformer 128 events. Stability: 96 events. Drop = baseline AUPRC − perturbed AUPRC; |Δp| = mean absolute probability change. Criterion = top-10 AUPRC drop exceeds the random-10 drop."),
  table([["Run", "Model", "Top-10 drop", "Random-10 drop", "Top-10 |Δp|", "Random-10 |Δp|", "AUPRC-deletion criterion", "Stability Jaccard / Spearman", "Explanation p95"],
    ["Regime, seed 42", "Transformer", "0.262", "0.000", "0.479", "0.005", "met", "0.82–1.00 / 1.00", "11.1 ms"],
    ["Regime, seed 42", "R-GCN (event features)", "0.435", "0.000", "0.512", "0.007", "met", "0.82–1.00 / 1.00", "28.8 ms"],
    ["Regime, seed 42", "R-GCN (flow features)", "0.000", "0.000", "0.002", "0.000", "not applicable (no effect)", "0.43 / 0.31–0.36", ""],
    ["Intensity κ = 0", "Transformer", "−0.043 (AUPRC rises)", "−0.023", "0.259", "0.118", "**not met**", "1.00 / 1.00", "19.5 ms"],
    ["Intensity κ = 0", "R-GCN (event features)", "0.036", "0.012", "0.243", "0.114", "met", "1.00 / 1.00", "44.7 ms"],
    ["Intensity κ = 0", "R-GCN (flow features)", "0.007", "0.000", "0.062", "0.000", "met (small)", "0.54 / 0.52", ""],
    ["Intensity κ = 1", "Transformer", "0.041", "−0.008", "0.219", "0.078", "met", "1.00 / 1.00", "6.9 ms"],
    ["Intensity κ = 1", "R-GCN (event features)", "0.057", "0.009", "0.223", "0.089", "met", "0.82–1.00 / 1.00", "59.1 ms"],
    ["Intensity κ = 1", "R-GCN (flow features)", "0.004", "0.000", "0.059", "0.000", "met (small)", "0.54 / 0.73", ""]], [1100, 1400, 1000, 1000, 900, 900, 1200, 1100, 760], { size: 14 }),
  new Paragraph({ spacing: { after: 120 } }),
  body("Four observations follow, each specific to the checkpoint tested. First, the R-GCN's event-node attribution satisfied the AUPRC-deletion criterion in all three settings and moved predictions far more than random evidence did (|Δp| 0.22–0.51 versus 0.01–0.11), with top-10 overlap of 0.82–1.00 under perturbation. Second, the Transformer's attribution satisfied the criterion on the regime target and at κ = 1 but not at κ = 0, where zeroing its ten top-ranked features raised AUPRC by 0.043 on the 128-event sample, more than random removal did. The predictions did respond to those features—the mean absolute probability change was 0.259 for top-ranked removal against 0.118 for random removal—so the correct reading is that the explanation did not satisfy the chosen AUPRC-deletion criterion, not that the model ignored the attributed features; in that setting the ranking-based criterion and the probability-based criterion disagree, and the explanation should not be presented as validated. Third, the R-GCN's flow-level attributions have small effects and are unstable (Jaccard 0.43–0.54), consistent with the small per-flow contribution in Section 4.7.3; relation-level explanations must rest on removal tests, because relation-weight norm correlates inconsistently with removal effect (Spearman +0.03, −0.14, +0.77 across the three runs). Fourth, explanation latency on prepared inputs is 7–20 ms (Transformer) and 29–59 ms (R-GCN local subgraph with attribution) at p95. A comparison against five random draws in three single-seed runs cannot establish general explanation fidelity; it establishes whether these checkpoints pass these checks."),
  body("The earlier package on the v2 checkpoints (fidelity 0.193 versus 0.009 mean absolute probability change; stability 0.778 / 0.802; relation-norm Spearman −0.371) is retained in the companion package as history; the tabular attribution-tracking test of Section 4.6.5 (physical-block importance 0.012 → 0.327 with κ, flat under the shuffled control) remains the only test against injected ground truth and applies to the random-forest explanations. Any R-GCN checkpoint replaced by the normalization rerun must be re-validated with the same package."),
'''
src = src.replace(old48, new48)
rep('''Explanation quality was validated on the final checkpoints of three representative runs (single seed each, 96-event evaluation subset) and against injected ground truth at the tabular level; the Transformer's attribution failed fidelity at κ = 0, flow-level attributions were unstable, and no validation involved operators."),''',
    '''Explanation validation is checkpoint-specific diagnostic evidence from three single-seed runs (fidelity on 1,828 / 1,015 events for the R-GCN and 128 for the Transformer; stability on 96 events; five random draws as the comparator); it does not establish general explanation fidelity. The Transformer's attribution did not meet the AUPRC-deletion criterion at κ = 0, flow-level attributions were unstable, and no validation involved operators."),''')

# ------------------------------------------------------------ latency boundaries (2.6.11 contradiction, 3.8.4, 4.9)
ch2 = json.loads((W / "chapter2_blocks.json").read_text())
for b in ch2:
    if b["t"] == "p" and "In this study the latency reported for every model family is inference on prepared inputs" in b["x"]:
        b["x"] = b["x"].split(" In this study the latency reported for every model family")[0] + " This study reports two of these boundaries and labels each: the standardized protocol of Section 4.9 measures from an in-memory raw event record to a score, including model-specific preparation but excluding feature aggregation, alignment, ingestion, and transport; the local-inference and explanation timings of Sections 4.7 and 4.8 are prepared-component measurements on an already constructed tensor or subgraph. No end-to-end operational latency was measured."
(W / "chapter2_blocks.json").write_text(json.dumps(ch2, indent=0))
rep('''Latency is measured as inference on prepared inputs (precomputed local subgraphs for the R-GCN, precomputed sequences for the Transformer, and assembled feature vectors for the tabular models); it excludes feature aggregation and alignment."),''',
    '''Two latency boundaries are reported and labeled wherever a figure appears: the standardized cross-family protocol measures from an in-memory raw event record to a score, including model-specific preparation (sequence assembly, local-subgraph construction, feature-vector assembly) but excluding feature aggregation and alignment; the R-GCN local-inference figures in the model tables and the explanation timings are prepared-component measurements on an already constructed subgraph or tensor."),''')
rep('''  body("All latencies are inference on prepared inputs—precomputed sequences, local subgraphs, or assembled feature vectors—and exclude feature aggregation and alignment. Under the standardized protocol (200 events, 20 warm-ups, three repetitions, one thread) p95 latencies were''',
    '''  body("Two boundaries are reported. The standardized cross-family protocol measures from an in-memory raw event record to a score, including model-specific preparation but excluding feature aggregation, alignment, ingestion, and transport; the R-GCN local-inference figures in Tables 4.6 and 4.12 and the explanation timings in Table 4.16 are prepared-component measurements on an already constructed subgraph or tensor, and are not comparable with the standardized figures. Under the standardized protocol (200 events, 20 warm-ups, three repetitions, one thread) p95 latencies were''')
rep('''Trained R-GCN local-subgraph inference remained at 3–11 ms p95 across all eleven ablation runs and 3.1–3.6 ms across the twenty ten-seed cells, two orders of magnitude inside the 500 ms bound. Hardware differs between the alignment analyses (single-core Linux container) and the neural runs (author's workstation); within-family comparisons are made on the same hardware."),''',
    '''Trained R-GCN local-subgraph inference (prepared-component boundary) remained at 3–11 ms p95 across all eleven ablation runs and 3.1–3.6 ms across the twenty ten-seed cells, two orders of magnitude inside the 500 ms bound. Hardware differs between the alignment analyses (single-core Linux container) and the neural runs (author's workstation); within-family comparisons are made on the same hardware."),''')

# ------------------------------------------------------------ 4. statistical claims and protocol history
rep('''All intervals are bin-cluster bootstraps (1,000 resamples of bins with replacement; 300 in the tabular grid) on AUPRC and on paired differences computed on identical events.''',
    '''Within-cell intervals are bin-cluster bootstraps (1,000 resamples of bins with replacement; 300 in the tabular grid) on AUPRC and on paired differences computed on identical events; across-seed inference uses seed-level t-intervals, as distinguished below.''')
rx(r'A block-size sensitivity analysis on the saved cyber-LR predictions.*?bin intervals are reported as approximate\.',
   '''A limited robustness check on the saved cyber-LR predictions (κ = 0, σ = 0, five seeds) compared interval widths across resampling units: for the AUPRC of a single model the mean 95% width was 0.042 at the event level, 0.207 with 240 s bins, 0.173 with 480 s blocks, and 0.180 with 960 s blocks, so enlarging the block beyond 240 s did not widen that interval; for the paired 120 s jitter loss the width was 0.047, 0.115, 0.137, and 0.108 respectively, so it widened at 480 s before narrowing at 960 s. The check therefore shows that event-level intervals are far too narrow and that 240 s bins remove most of the detectable dependence for the metrics examined; it does not establish that 240 s bins are independent or that the bin intervals have nominal coverage, and with 7–27 clusters the bootstrap is coarse. Bin intervals are reported as approximate.''')
rep('''A gain counts as detected when its seed mean reaches the pre-registered margin and every seed's bin-cluster interval excludes zero;''',
    '''A gain counts as detected when its seed mean reaches the pre-specified margin and every seed's bin-cluster interval excludes zero;''')
rep('''The original hypotheses (H1: event-time versus processing-time MAE ≥ 1 s; H2: R-GCN − Transformer ≥ 0.03 on the regime target; H3: lag/relation ablation gain ≥ 0.05 under 500 ms) were revised for three reasons established in this study: the original H1 was true by definition and measured a quantity with no downstream effect; the regime target is a ceiling on which model comparisons are uninformative; and the R-GCN of all earlier comparisons was insufficiently trained under its original budget. Table 3.5 maps each revised hypothesis to its test."),''',
    '''The original hypotheses (H1: event-time versus processing-time MAE ≥ 1 s; H2: R-GCN − Transformer ≥ 0.03 on the regime target; H3: lag/relation ablation gain ≥ 0.05 under 500 ms) were specified prospectively in the praxis proposal (SEAS 8499, autumn 2025). They were revised for three reasons established in this study: the original H1 was true by definition and measured a quantity with no downstream effect; the regime target is a ceiling on which model comparisons are uninformative; and the R-GCN of all earlier comparisons was insufficiently trained under its original budget. The protocol history is as follows, and the word pre-specified in this praxis refers to it. H1′, H2′, and H3′ with their margins and the detection rule were written on 19 September 2026, before the coupling grid, the ten-seed cells, and the training-budget ablation were run, but after the v1–v3 alignment audits and the regime-target results had been examined; H4 and H5 were added on 19–20 September 2026 before the runs that test them. H5's comparator (validation-selected best unimodal model) and the nonzero-jitter conditions were amended on 23 September 2026 after external review, with the coupling grid already collected; the H5 outcome is therefore post hoc with respect to comparator choice and the jitter findings are exploratory. No hypothesis rule was changed after its result was known except as stated here. Table 3.5 maps each revised hypothesis to its test."),''')
src = src.replace("pre-registered", "pre-specified")
rep('''"Seed-count closure for H2′: at ten seeds the margin test has p = 0.09 at κ = 0; twenty seeds at the two κ levels are inexpensive and would settle whether the advantage reaches 0.03.",''',
    '''"Additional seeds for H2′: at ten seeds the seed-level interval at κ = 0 spans 0.011 to 0.120; additional seeds at the two κ levels would improve the precision of the estimate, although with 27 resampling bins per cell the within-cell uncertainty would remain.",''')
rep('''and that a larger seed count would be needed to establish the margin.''', '''and that additional seeds could improve the precision of that estimate.''')

# ------------------------------------------------------------ 5. consistency items
rep('''"**RQ2.** Does a relation-aware graph model that reasons over flow neighbourhoods and event-to-event links outperform a sequential Transformer on the same inputs, on a target that is not saturated?",''',
    '''"**RQ2.** Does a relation-aware graph model that reasons over flow neighbourhoods and event-to-event links outperform a sequential Transformer on the same held-out events, on a target that is not saturated?",''')
rep('''["Event-only model", "The R-GCN with all relations removed except an event self-loop, equivalent to an MLP on the event node; its gap to the full model is the value of relational structure."]''',
    '''["Event-only model", "The R-GCN with all relations removed except an event self-loop, equivalent to an MLP on the event node. Its gap to the full model, on the same held-out events, is the value of the relations together with the flow-level evidence they carry; it does not isolate message passing on identical inputs."]''')
rep('''its gap to the full model measures the value of relational structure (H4).''', '''its gap to the full model, on the same held-out events, measures the value of the relations together with the flow-level evidence they carry (H4); it does not isolate architecture on identical inputs, because the event-only model sees no flow nodes.''')
rep('''Fifth, once trained, relational modeling of flow evidence is more often better than sequential modeling on the same inputs, with an advantage attributable to the relations and the flow-level evidence they carry; the pre-specified margin was not established.''',
    '''Fifth, once trained, relational modeling of flow evidence was more often better than sequential modeling on the same held-out events, with an advantage attributable to the relations and the flow-level evidence they carry; the pre-specified margin was not established, and the R-GCN figures await the normalization rerun.''')
rep('''and its 16 label-blind nearest flows are flow nodes carrying 12 transformed per-flow fields.''',
    '''and its 16 label-blind nearest flows are flow nodes carrying three numeric and one categorical raw per-flow fields (ports, protocol, duration), which the training-fitted preprocessor expands to 83 columns on the regime target and 26 in the intensity cells (event nodes: 129 and 100 columns).''')
