rep('''["Cross-regime (primary)", "S1", "1,015 / 813", "0.555 (= prevalence)", "undefined (constant score)"]''', '''["Cross-regime (primary)", "S1", "1,015 / 813", "0.555 (= prevalence)", "0.5 (constant score)"]''')
